import random
import string


def generate_test_case():

    def generate_molecule():
        return random.choice(string.ascii_uppercase) + ''.join(random.choices(string.ascii_lowercase, k=random.randint(0, 2)))

    def generate_formula(min_len=1, max_len=1000):
        length = random.randint(min_len, max_len)
        formula = ''

        while len(formula) < length:
            if formula and random.random() < 0.3:  # With 30% chance, wrap the last molecule in parentheses and add a count
                closing_parenthesis_index = formula.rfind(')')  # Find last closing parenthesis
                if closing_parenthesis_index == -1:  # If there is no closing parenthesis, take the whole formula
                    opening_parenthesis_index = 0
                else:  # Otherwise, start from the parenthesis after the last closing parenthesis
                    opening_parenthesis_index = closing_parenthesis_index + 1

                formula = formula[:opening_parenthesis_index] + '(' + formula[opening_parenthesis_index:] + ')' + str(random.randint(2, 9))
            else:  # With 70% chance, add a new molecule
                formula += generate_molecule() + str(random.randint(1, 9))

        # If the resulting formula is too long, remove the last molecule
        if len(formula) > max_len:  
            return formula[:formula.rfind('(')]
        else:
            return formula

    return generate_formula()
